class Form:
    def flaeche(self):
        return 0

class Kreis(Form):
    def __init__(self, r):
        self.r = r
    def flaeche(self):
        return round(3.14 * self.r ** 2, 2)

class Rechteck(Form):
    def __init__(self, a, b):
        self.a, self.b = a, b
    def flaeche(self):
        return self.a * self.b

formen = [Kreis(1), Rechteck(2, 3)]
for f in formen:
    print(f.flaeche())
# 3.14
# 6

class Drucker:
    def ausgeben(self, text):
        print("Papier:", text)

class Beamer:
    def ausgeben(self, text):
        print("Leinwand:", text)

def praesentiere(geraet):
    geraet.ausgeben("Projekt POS")

praesentiere(Drucker())
praesentiere(Beamer())
# Papier: Projekt POS
# Leinwand: Projekt POS

from abc import ABC, abstractmethod

class Form(ABC):
    @abstractmethod
    def flaeche(self):
        ...

    def beschreibung(self):
        return f"Fläche: {self.flaeche()}"

class Quadrat(Form):
    def __init__(self, a):
        self.a = a
    def flaeche(self):
        return self.a ** 2

print(Quadrat(3).beschreibung())
# Fläche: 9
f = Form()   # TypeError

